/// Native replay implementations for tls bindings.
#[inline]
fn destack_tls_context_close_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    handle: resource::TlsContextHandle,
) -> RuntimeResult<()> {
    let _ = &handle;

    binding.trace().run_binding_without_context(
        TLS_CONTEXT_CLOSE,
        binding.replay_payload_for(TLS_CONTEXT_CLOSE)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_tls_context_close(binding, handle)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_tls_context_close(binding, handle)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = TlsContextCloseReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    TlsContextCloseReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

