#[inline]
fn destack_tls_session_negotiated_alpn_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    handle: resource::TlsSessionHandle,
) -> RuntimeResult<vm::Value> {
    let result = binding.trace().run_binding(
        TLS_SESSION_NEGOTIATED_ALPN,
        binding.replay_payload_for(TLS_SESSION_NEGOTIATED_ALPN)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_tls_session_negotiated_alpn(binding, context, handle)
            }
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_tls_session_negotiated_alpn(
                    binding, context, handle,
                )
            }
        },
        |context, result| {
            let context = &context.read();
            if let Ok(value) = result {
                let result_value: VmSlice<u8> = value.clone();
                let result_recorded = result_value.read_bytes(context)?;
                let payload = TlsSessionNegotiatedAlpnReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    TlsSessionNegotiatedAlpnReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let context = &mut context.write();
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result = VmSlice::<u8>::from_bytes(context, value.as_ref())?;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_tls_session_negotiated_alpn_result(context, result)?;
    Ok(result)
}

